insert into public.assess_tests(key,title,intro,stop_after,sort,stop_mode) values ('alpha','Letter recognition (capitals, then lower case)','Read the letters out loud. You can say the name or the sound of each letter.',999,0,'consec'),('word','Word reading (graded list)','Read each word out loud. If you do not know a word, say "skip".',8,1,'consec'),('comp','Reading comprehension (graded passages)','Read the short text, then choose the best answer.',6,2,'consec'),('maths','Maths (graded items)','Work out each answer. Type it in, then tap Send.',5,3,'consec'),('listen','Listening comprehension','Listen carefully to each story. Then answer the questions out loud.',6,4,'consec'),('dsf','Digits forwards','Listen to the numbers. Then say them back in the same order.',2,5,'pair'),('dsb','Digits backwards','Listen to the numbers. Then say them backwards.',2,6,'pair'),('wsf','Remembering words','Listen to the words. Then say them back in the same order.',2,7,'pair') on conflict (key) do update set title=excluded.title,intro=excluded.intro,stop_after=excluded.stop_after,sort=excluded.sort,stop_mode=excluded.stop_mode;
