delete from public.assess_levels; delete from public.assess_items;
with p(lv,t) as (values (1,'Sam has a red kite. The wind is strong today. Sam runs to the park with his dog, Max. The kite flies high in the sky. Max barks at the kite. Sam laughs.'),(2,'Ben went to the beach with his gran. The sun was hot. They sat under a big red umbrella. Ben made a sandcastle with a tall tower. Then a wave came and washed it away. Ben felt sad. Gran said, "Let us make a new one." This time they built it far from the sea.'),(3,'On Saturday, Priya''s class visited a farm. First, they fed the lambs with warm milk from big bottles. The lambs pushed and wriggled, and milk dripped down their chins. Then the farmer showed them how to collect eggs. Priya was nervous because the hens pecked at her fingers, but she found three brown eggs. At the end of the day the children were tired and muddy. On the bus, Priya fell asleep with an egg box on her knee.'),(4,'Mia found a small, wet kitten behind the garden shed. It was shivering and very thin. Mia wrapped the kitten in her scarf and carried it inside. Her dad warmed some milk in a saucer. Soon the kitten stopped shaking and began to purr. Mia asked if they could keep it, but Dad said they must first check whether it belonged to someone.'),(5,'Long ago, people crossing the desert used camels. A camel can drink a lot of water in a few minutes. Then it can walk for days without another drink. Its hump does not hold water, as many people think. It stores fat that the camel can use for energy. Thick eyelashes protect its eyes from sand, and wide feet stop it sinking. This is why camels were called ''ships of the desert''.'),(6,'The lighthouse on Gull Rock had stood for over two hundred years. Every night, its great lamp swept across the dark water, warning sailors to keep away from the jagged rocks below. When electric lights arrived, nobody needed the keeper any more. The lighthouse was locked up and left to the wind and the salt. Years later, the villagers decided to repair it. They painted its tower, mended the stairs and opened it as a museum. Now visitors climb to the top each summer to see the view the keeper once knew.'),(7,'Scientists studying the Arctic have noticed that sea ice is forming later in autumn and melting earlier in spring than it did fifty years ago. For polar bears, which hunt seals from the ice, this shortens the season in which they can feed. Bears that cannot catch enough food in spring and summer must survive on their fat reserves until the ice returns. Some researchers argue that if the trend continues, fewer cubs will survive. Others point out that bears are adaptable and may find new food sources, although none of these provides as much energy as seal blubber. Both groups agree on one thing: more data are needed before firm predictions can be made.'),(8,'When the council announced plans to replace Millbrook Library with a car park, the response was swift. Within a week, a petition had gathered three thousand signatures. At the public meeting, a councillor insisted that ''the books are all online now anyway'', prompting a murmur of disbelief from the audience. A retired teacher then rose to describe how the library had taught her to read, and how, decades later, she volunteered there to teach others. Several students described the library as the only quiet place they could study. Though the council did not reverse its decision that evening, its chairman conceded that the strength of feeling had been ''greater than anticipated'', and promised to consider alternative sites. The campaigners left cautiously hopeful rather than triumphant.')), q(lv,n,sk,qt,op) as (values (1,1,'literal','What colour is Sam''s kite?','["Red", "Blue", "Green", "Yellow"]'),(1,2,'literal','Where does Sam run to?','["The park", "The shop", "School", "The beach"]'),(1,3,'literal','Who barks at the kite?','["Max", "Sam", "A bird", "Mum"]'),(1,4,'inference','Why does Sam laugh?','["He is having fun", "He is cross", "He is cold", "He is lost"]'),(2,1,'literal','Who did Ben go to the beach with?','["His gran", "His dad", "His friend", "His dog"]'),(2,2,'literal','What colour was the umbrella?','["Red", "Blue", "Yellow", "Green"]'),(2,3,'literal','What happened to the first sandcastle?','["A wave washed it away", "It fell over", "Gran stood on it", "The wind blew it down"]'),(2,4,'inference','Why did they build the new castle far from the sea?','["So the waves could not wash it away", "Because the sand was softer", "Because it was hotter there", "Because Gran liked walking"]'),(3,1,'literal','What did the children feed to the lambs?','["Warm milk", "Grass", "Corn", "Water"]'),(3,2,'literal','How many eggs did Priya find?','["Three", "Two", "Five", "Six"]'),(3,3,'vocabulary','What does the word ''wriggled'' mean?','["Moved about in a twisting way", "Sat very still", "Ran away", "Fell over"]'),(3,4,'inference','Why did Priya fall asleep on the bus?','["She was tired after a busy day", "She was bored", "She was feeling ill", "She was cold"]'),(4,1,'literal','Where did Mia find the kitten?','["Behind the garden shed", "In the kitchen", "Under a car", "At the park"]'),(4,2,'literal','What did Mia wrap the kitten in?','["Her scarf", "A towel", "A blanket", "Her coat"]'),(4,3,'inference','How can you tell the kitten felt better?','["It stopped shaking and began to purr", "It ran away", "It ate a fish", "It fell asleep outside"]'),(4,4,'inference','Why did Dad say they must wait before keeping the kitten?','["It might belong to someone else", "Kittens are not allowed indoors", "The kitten was too thin", "They had no milk left"]'),(5,1,'literal','What does a camel''s hump store?','["Fat", "Water", "Sand", "Food"]'),(5,2,'vocabulary','What does ''stores'' mean in this text?','["Keeps for later", "Throws away", "Hides from", "Sells"]'),(5,3,'literal','What do wide feet help a camel to do?','["Not sink into the sand", "Keep its eyes clean", "Drink more water", "Find food"]'),(5,4,'inference','Why were camels called ''ships of the desert''?','["They carried people safely across a sea of sand", "They could swim", "They were shaped like boats", "They lived near the sea"]'),(6,1,'literal','What was the job of the great lamp?','["To warn sailors about the rocks", "To light the village streets", "To help fish swim near", "To signal the keeper''s family"]'),(6,2,'inference','Why was the keeper no longer needed?','["Electric lights arrived", "Sailors stopped using the sea", "The lamp broke", "The village moved away"]'),(6,3,'vocabulary','What does the word ''jagged'' mean?','["Rough with sharp edges", "Smooth and flat", "Very tall", "Brightly coloured"]'),(6,4,'inference','What has finally happened to the lighthouse?','["It has been repaired and opened to visitors", "It has been knocked down", "It is still locked up", "It has been sold to the keeper"]'),(7,1,'inference','Why is earlier melting a problem for polar bears?','["They have less time to hunt seals from the ice", "The seals move to warmer water", "The ice becomes too thick to walk on", "They cannot find places to sleep"]'),(7,2,'literal','What must bears do when they cannot catch enough food?','["Live off their stored fat", "Travel south for the winter", "Eat the ice", "Sleep until spring"]'),(7,3,'inference','What is the main disagreement between the researchers?','["Whether bears will be able to cope by finding new foods", "Whether sea ice is melting at all", "Whether bears hunt seals", "Whether Arctic summers are getting shorter"]'),(7,4,'literal','What do both groups of researchers agree on?','["More data are needed before predictions are made", "Cub numbers will fall", "Bears will adapt easily", "Seal blubber is not important"]'),(8,1,'literal','What did the council plan to do with the library?','["Replace it with a car park", "Move it online", "Sell it to a school", "Repair it"]'),(8,2,'inference','Why did the audience murmur in disbelief at the councillor''s comment?','["They did not accept that online books made the library unnecessary", "They had not heard what he said", "They thought the meeting was too long", "They wanted more car parking"]'),(8,3,'vocabulary','What does ''conceded'' suggest about the chairman''s comment?','["He admitted something, perhaps reluctantly", "He lost his temper", "He told a joke", "He refused to listen"]'),(8,4,'inference','Why were the campaigners ''cautiously hopeful rather than triumphant''?','["They were listened to, but the decision had not changed", "They had won completely", "They had given up", "They had found another library"]')) insert into public.assess_items(test_key,ord,item_id,level,skill,payload,answer) select 'comp',row_number() over(order by q.lv,q.n),'c'||q.lv||q.n,q.lv,q.sk,jsonb_build_object('type','mcq','passage',p.t,'q',q.qt,'options',q.op::jsonb),'{"correct":0}'::jsonb from q join p on p.lv=q.lv;
with p(lv,t) as (values (1,'Tom has a little boat. It is blue and white. Today he takes it to the pond. A duck swims up to the boat. Tom gives the duck some bread. Quack, quack, says the duck.'),(2,'Lily wanted to make a cake for Grandad''s birthday. She mixed butter, sugar and eggs in a big bowl. Then she added the flour and stirred it well. While the cake was in the oven, Lily made a card with a balloon on it. The cake smelled so good! Grandad said it was the best cake he had ever eaten.'),(3,'The explorers had been walking through the jungle for three days. Their feet were sore and their water was nearly gone. Suddenly, Maya heard a faint splashing sound. She pushed aside some enormous leaves and gasped. A sparkling waterfall tumbled into a clear blue pool. "We are saved!" she shouted.'),(4,'Mr Patel sold spices in the old market. Each morning the air smelled of cinnamon, cumin and pepper. Customers often tried to bargain, but he would not lower his prices. He believed his spices were worth every penny. One day a girl asked if he would swap some cinnamon for a drawing. Mr Patel laughed, looked at the picture carefully and agreed. The drawing hung above his barrels for many years.'),(6,'Maria had trained for the swimming gala for months, getting up at five every morning to practise before school. On the day of the race, however, her goggles snapped as she dived in. For a moment she thought about stopping, but the memory of all those early mornings pushed her on. She finished third, with stinging eyes and a grin that would not go away. Her coach said later that determination had mattered more than the medal.'),(9,'Archaeologists digging at a Roman fort in northern England found some wooden writing tablets. The wet soil had kept them safe. The thin leaves, no bigger than a postcard, carry ink messages written nearly two thousand years ago. One is a birthday invitation, thought to be among the oldest writing by a woman in Britain. Another is a request for warm socks, sent to a soldier. Historians value such everyday notes. Official records tell them about generals and battles, but these tablets show how ordinary people lived.'),(11,'The arrival of cheap plastics changed twentieth-century life. Yet the qualities that made them attractive, durability and resistance to decay, have become environmental liabilities. A bottle thrown away today may last for centuries, breaking into smaller pieces rather than disappearing. Some campaigners want outright bans on single-use items. They argue that individual recycling cannot offset the scale of production. Manufacturers reply that plastics reduce food waste, and that abrupt bans might raise carbon emissions through heavier alternatives. Most analysts conclude that redesign, regulation and recycling together offer the most realistic path forward.')), q(lv,n,k,sk,qt,ac) as (values (1,1,4,'literal','What colour is Tom''s boat?','Blue and white (blue is enough)'),(1,2,4,'literal','Where does Tom take his boat?','To the pond'),(1,3,4,'literal','Who swims up to the boat?','A duck'),(1,4,4,'inference','What does Tom give the duck?','Bread'),(2,1,4,'literal','Who was the cake for?','Her grandad'),(2,2,4,'literal','What did Lily make while the cake was in the oven?','A card'),(2,3,4,'literal','What picture was on the card?','A balloon'),(2,4,4,'inference','How do we know that Grandad liked the cake?','He said it was the best cake he had ever eaten'),(3,1,4,'literal','How long had the explorers been walking?','Three days'),(3,2,4,'literal','What did Maya hear?','A splashing sound (water)'),(3,3,4,'vocabulary','What does ''enormous'' mean?','Very big / huge / giant'),(3,4,4,'inference','Why did Maya shout, ''We are saved''?','They had found water / they had been thirsty and now had a drink'),(4,1,4,'literal','What did Mr Patel sell?','Spices'),(4,2,4,'literal','What did the girl offer in exchange for cinnamon?','A drawing / a picture'),(4,3,4,'vocabulary','What does ''bargain'' mean in this story?','To argue about or try to lower the price'),(4,4,4,'inference','Why do you think Mr Patel hung the drawing above his barrels?','Any reasonable reason: he liked it / it was special / he was proud of it / it reminded him of the girl'),(6,1,4,'literal','When did Maria practise?','At five in the morning / before school'),(6,2,4,'literal','What went wrong in the race?','Her goggles snapped'),(6,3,4,'inference','Why did Maria keep swimming?','She remembered all her early-morning training / she did not want to waste it / she was determined'),(6,4,4,'inference','What did the coach mean when she said determination mattered more than the medal?','Trying hard and not giving up was more important than winning a prize'),(9,1,4,'literal','What preserved the tablets?','The waterlogged / wet soil'),(9,2,4,'literal','How old are the tablets?','Nearly two thousand years old'),(9,3,4,'vocabulary','What does ''value'' mean when historians ''value'' these notes?','Think they are important / treasure them'),(9,4,4,'inference','Why do historians value these everyday notes?','They show how ordinary people lived, not just generals and battles'),(11,1,4,'literal','Which qualities made plastics attractive but are now a problem?','Durability and resistance to decay (lasting a long time / not rotting)'),(11,2,4,'inference','Why do some campaigners think recycling alone is not enough?','The amount of plastic produced is too large for individual recycling to cancel out'),(11,3,4,'vocabulary','What does ''abrupt'' mean?','Sudden / without warning'),(11,4,4,'inference','What do manufacturers fear might happen if single-use plastics are banned suddenly?','Heavier replacement materials could raise carbon emissions')) insert into public.assess_items(test_key,ord,item_id,level,skill,payload,answer) select 'listen',row_number() over(order by q.lv,q.n),'l'||q.lv||q.n,q.lv,q.sk,jsonb_build_object('type','listen','mode','story','passage',p.t,'q',q.qt,'first',q.n=1,'qno',q.n,'of',q.k),jsonb_build_object('accept',q.ac) from q join p on p.lv=q.lv;
